namespace AssetTracker.Models;

/// <summary>
/// Represents one of the five fixed departments (Department table). Employees reference a department by DepartmentId. At this stage it does not need to load departments yet, so this class mainly completes the domain model and will be used by employee management in Part 3.
/// </summary>

public class Department
{

    /// Primary key, generated by the database (IDENTITY).

    public int DepartmentId { get; set; }

    /// Display name, e.g. "Finance" or "Information Technology".

    public string DepartmentName { get; set; } = "";
}